using System;using System.IO;using System.Reflection;using System.Linq;using System.Windows;using System.Windows.Controls.Primitives;using System.Windows.Threading;using System.Drawing;using DesktopNotes;
namespace DesktopNotes {static class PlacementSimulation {internal static Rectangle[] Screens=new[]{new Rectangle(0,0,1920,800)};}}
class PlacementRecoveryTests {
 static int checks;static readonly BindingFlags Private=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL: "+name);checks++;Console.WriteLine("PASS: "+name);}
 static void Pump(){var frame=new DispatcherFrame();Dispatcher.CurrentDispatcher.BeginInvoke(DispatcherPriority.ApplicationIdle,new Action(()=>frame.Continue=false));Dispatcher.PushFrame(frame);}
 static void Display(MainWindow w,params Rectangle[] areas){PlacementSimulation.Screens=areas;typeof(MainWindow).GetMethod("DisplayChanged",Private).Invoke(w,new object[]{null,EventArgs.Empty});Pump();w.UpdateLayout();}
 static bool At(MainWindow w,double x,double y){var b=w.Host.Bounds();return Math.Abs(b[0]-x)<1.1&&Math.Abs(b[1]-y)<1.1;}
 [STAThread]static int Main(string[] args){MainWindow w=null;try{string mode=args.Length>0?args[0]:"transient",folder=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"fixture-"+mode+"-"+Guid.NewGuid().ToString("N"));var store=new Storage(folder);var state=new NoteState();state.Settings.Left=1950;state.Settings.Top=439;state.Settings.Width=610;state.Settings.Height=953;state.Settings.Locked=true;state.Settings.AnimationsEnabled=mode=="snap";state.Settings.QuickAddShortcut="Ctrl+Alt+Shift+F8";state.Settings.QuickAddDraft="isolated placement draft";new NoteService(state).Add("isolated placement fixture","inbox");store.Save(state);if(mode=="normal"||mode=="shutdown"||mode=="loss"||mode=="snap")PlacementSimulation.Screens=new[]{new Rectangle(0,0,2560,1392)};var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};w=new MainWindow(store,store.Load(),true);app.MainWindow=w;w.Show();w.UpdateLayout();Pump();
 if(mode=="transient"){
  Check(!At(w,1950,439),"unavailable original location has a visible temporary fallback");w.Save();var saved=store.Load().Settings;Check(saved.Left==1950&&saved.Top==439,"saving while the startup display is smaller preserves the original location");Check(saved.Width==610&&saved.Height==953,"temporary resizing preserves the preferred dimensions");
  Display(w,new Rectangle(0,0,2560,1392));Check(At(w,1950,439),"original location returns after the normal display area returns");Check(Math.Abs(w.ActualHeight-953)<1.1,"original dimensions return with the display");w.Save();Check(store.Load().Notes.Count==1&&store.Load().Settings.QuickAddDraft=="isolated placement draft","notes and quick-add draft survive fallback and restoration");
  Display(w,new Rectangle(0,0,1920,800));w.Save();Check(store.Load().Settings.Left==1950,"later display changes also preserve the preferred location");var timerField=typeof(MainWindow).GetField("placementRetryTimer",Private);var timer=timerField==null?null:timerField.GetValue(w) as DispatcherTimer;Check(timer!=null&&timer.IsEnabled,"temporary fallback keeps rechecking for a ready display");
  PlacementSimulation.Screens=new[]{new Rectangle(0,0,2560,1392)};var until=DateTime.UtcNow.AddSeconds(5);while(!At(w,1950,439)&&DateTime.UtcNow<until){Pump();System.Threading.Thread.Sleep(30);}Check(At(w,1950,439),"display readiness is detected even without a display-change event");Check(!timer.IsEnabled,"retry polling stops after the preferred location returns");
  Display(w,new Rectangle(0,0,1920,800));w.Exit();Check(store.Load().Settings.Left==1950&&store.Load().Settings.Height==953,"normal exit in a temporary display preserves the original geometry");Check(!timer.IsEnabled,"window exit stops the placement retry timer");w=null;
 }else if(mode=="move"){
  w.Host.Move(100,200);typeof(MainWindow).GetField("moving",Private).SetValue(w,true);typeof(MainWindow).GetField("moveStarted",Private).SetValue(w,true);typeof(MainWindow).GetMethod("EndMove",Private).Invoke(w,null);Check(store.Load().Settings.Left==100&&store.Load().Settings.Top==200,"deliberate dragging replaces a temporary fallback with the user's new position");Display(w,new Rectangle(0,0,2560,1392));Check(At(w,100,200),"display return preserves a newly chosen drag position");
 }else if(mode=="resize"){
  w.Width=640;w.Height=700;w.UpdateLayout();w.Host.Move(100,200);var grips=(System.Collections.Generic.List<Thumb>)typeof(MainWindow).GetField("grips",Private).GetValue(w);grips[0].RaiseEvent(new DragCompletedEventArgs(0,0,false){RoutedEvent=Thumb.DragCompletedEvent});var saved=store.Load().Settings;Check(saved.Left==100&&saved.Top==200&&saved.Width==640&&saved.Height==700,"deliberate resizing commits the visible geometry during fallback");Display(w,new Rectangle(0,0,2560,1392));Check(At(w,100,200)&&Math.Abs(w.ActualWidth-640)<1.1,"display return keeps a user's resized geometry");
 }else if(mode=="reset"){
  w.RestorePlacement();var expected=w.Host.Bounds();var saved=store.Load().Settings;Check(Math.Abs(saved.Left-expected[0])<1.1&&Math.Abs(saved.Top-expected[1])<1.1,"tray restore explicitly saves the requested recovery position");Display(w,new Rectangle(0,0,2560,1392));Check(At(w,expected[0],expected[1]),"automatic restoration does not undo the tray recovery action");
 }else if(mode=="recovery"){
  var old=w;var source=System.Windows.Interop.HwndSource.FromHwnd(new System.Windows.Interop.WindowInteropHelper(old).Handle);source.Dispose();Pump();w=app.MainWindow as MainWindow;Check(w!=null&&w!=old,"lost window source recreates the window during a temporary placement");Check(w.Service.State.Settings.Left==1950&&w.Service.State.Settings.Height==953,"window recovery preserves the preferred geometry during fallback");Check(store.Load().Notes.Count==1,"fallback window recovery preserves the fictional note");Display(w,new Rectangle(0,0,2560,1392));Check(At(w,1950,439),"the recovered window returns to the original position when the display returns");
 }else if(mode=="shutdown"){
  w.Host.Move(2296,808);w.Service.Add("saved during shutdown fixture","inbox");w.Save();var saved=store.Load();Check(saved.Settings.Left==1950&&saved.Settings.Top==439,"an unrequested native offset cannot replace the preferred location during an ordinary save");Check(saved.Notes.Count==2,"saving content still works while native geometry is displaced");w.Exit();w=null;Check(store.Load().Settings.Left==1950&&store.Load().Settings.Top==439,"exit preserves the last user-selected location after a shutdown-like offset");
 }else if(mode=="loss"){
  w.Host.Move(2296,808);var old=w;System.Windows.Interop.HwndSource.FromHwnd(new System.Windows.Interop.WindowInteropHelper(w).Handle).Dispose();Pump();w=app.MainWindow as MainWindow;Check(w!=old&&w.Service.State.Settings.Left==1950&&w.Service.State.Settings.Top==439,"native window destruction never samples displaced geometry into user preferences");Check(At(w,1950,439),"window recovery restores the last user-selected location despite an external offset");Check(store.Load().Settings.Left==1950,"native-loss recovery writes the original preferred location");
 }else if(mode=="snap"){
  w.Host.Move(1940,430);typeof(MainWindow).GetField("moving",Private).SetValue(w,true);typeof(MainWindow).GetField("moveStarted",Private).SetValue(w,true);typeof(MainWindow).GetMethod("EndMove",Private).Invoke(w,null);var deadline=DateTime.UtcNow.AddSeconds(4);while(DateTime.UtcNow<deadline){Pump();var t=typeof(MainWindow).GetField("snapTimer",Private).GetValue(w) as DispatcherTimer;if(t==null||!t.IsEnabled)break;System.Threading.Thread.Sleep(20);}var b=w.Host.Bounds();var saved=store.Load().Settings;Check(Math.Abs(b[0]-1950)<1.1&&Math.Abs(b[1]-439)<1.1,"dragging near the edge completes the animated snap");Check(Math.Abs(saved.Left-b[0])<1.1&&Math.Abs(saved.Top-b[1])<1.1,"animated snap saves its final user-chosen coordinates");
 }else if(mode=="normal"){
  Check(At(w,1950,439),"a valid saved position stays unchanged at normal startup");w.Host.Move(400,200);w.Width=500;w.Height=600;w.UpdateLayout();var normalGrips=(System.Collections.Generic.List<Thumb>)typeof(MainWindow).GetField("grips",Private).GetValue(w);normalGrips[0].RaiseEvent(new DragCompletedEventArgs(0,0,false){RoutedEvent=Thumb.DragCompletedEvent});var saved=store.Load().Settings;Check(saved.Left==400&&saved.Top==200&&saved.Width==500&&saved.Height==600,"ordinary position and size saves still work");
 }
 if(w!=null){w.Exit();w=null;}Console.WriteLine("ALL "+checks+" PLACEMENT CHECKS PASSED ("+mode+")");return 0;}catch(Exception ex){Console.Error.WriteLine(ex);if(w!=null)try{w.Exit();}catch{}return 1;}}
}


